	fake_clock_advance_sec(&f.state, 2 * 60 * 60 + 1);
	fixture_run_timers(&f);
	return test_event_count(&f.state, TEST_EVENT_TIMER, 0) > 0 &&
		test_event_count(&f.state, TEST_EVENT_TX_PACKET, 0) == 0
		? RESULT_PASS : RESULT_FAIL;
